import java.util.concurrent.Executors;
import java.util.stream.IntStream;

public class VirtualThreadDemo {
    public static void main(String[] args) throws InterruptedException {
        // Using an ExecutorService configured for virtual threads
        try (var executor = Executors.newVirtualThreadPerTaskExecutor()) {
            IntStream.range(0, 10_000).forEach(i -> {
                executor.submit(() -> {
                    // Simulate blocking I/O operation
                    Thread.sleep(1000);
                    return i;
                });
            });
        } // Executor scope closes here, automatically awaiting all tasks
        System.out.println("All 10,000 tasks completed successfully using virtual threads.");
    }
}
